// ---- post-proceso ----
(function(){
  let seed=7; const rnd=()=>{seed=(seed*1103515245+12345)&0x7fffffff;return seed/0x7fffffff;};
  const shuf=q=>{ // q = [txt,[ok,...wrong],0,exp] → mezcla
    const ok=q[1][0]; const a=q[1].slice(); for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]];}
    return [q[0],a,a.indexOf(ok),q[3]];};
  COURSES.forEach(c=>{ if(c.id!==COURSES[0].id) return;
    c.modules.forEach(m=>{
      const base=m.lessons.slice();
      base.forEach(l=>{ (QX[l.id]||[]).forEach(q=>l.quiz.push(shuf(q))); });
      const cmds=[]; base.forEach(l=>{cmds.push('## '+l.id+' · '+l.t); cmds.push(l.cmds.split('\n').filter(x=>!x.startsWith('## ')).join('\n'));});
      const ml=ML[m.n];
      m.lessons.push({id:'M'+m.n,t:'Práctica integrada del módulo',isMod:true,mod:null,
        sum:'Repaso de **todo el módulo '+m.n+' · '+m.title+'** en un solo lugar: una autoevaluación que mezcla todas las clases y un laboratorio de nivel intermedio que combina los comandos. Las clases del módulo: '+base.map(l=>l.id+' '+l.t).join(' · ')+'.',
        cmds:cmds.join('\n'),fig:null,star:false,
        lab:ml.t,intro:ml.intro,
        quiz:MQ[m.n].map(shuf),cards:[]});
    });
  });
})();
