    const mods = spec.map(([n, title, items]) => {
      const lessons = items.map(it => {
        if (typeof it === "string") { if (old[it]) { used.add(it); return old[it]; } return PH(it, "Sesión " + it); }
        const [id, t, from] = it; if (from && old[from]) { used.add(from); return Object.assign({}, old[from], { id, t }); } return PH(id, t);
      });
      return { n, title, lessons };
    });
    // nada se pierde: lo que no entró en la lista se agrega a su módulo
